def get_positive_integer():
    """
    Prompts the user to enter a positive integer and validates the input.
    """
    while True:
        try:
            user_age = int(input("Please enter your age (a positive integer): "))
            if user_age > 0:
                return user_age
            else:
                print("Your age must be a positive integer. Please try again.")
        except ValueError:
            print("That's not a valid integer. Please try again.")

# Call the function to get user input
